// Merge the per-batch card files into deep-nlf/<a1|a2|b>-<zh|en>.js (loaded lazily by app.js).
// usage: node tools/deep/bundle.js <batch-out-dir>
const fs = require('fs'), path = require('path');
const dir = process.argv[2], dest = path.join(__dirname, '..', '..', 'deep-nlf');
fs.mkdirSync(dest, { recursive: true });
const sizes = {};
for (const book of ['a1', 'a2', 'b']) for (const lang of ['zh', 'en']) {
  const files = fs.readdirSync(dir).filter(f => f.startsWith(book + '-') && f.endsWith(`.${lang}.json`)).sort();
  if (!files.length) continue;
  const all = {};
  for (const f of files) Object.assign(all, JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')));
  const name = { zh: 'DEEP', en: 'DEEP_EN' }[lang];
  const body = Object.entries(all).map(([k, v]) => ` ${JSON.stringify(k)}: ${JSON.stringify(v)}`).join(',\n');
  const out = `// In-depth word cards (${lang === 'zh' ? '中文' : 'English'}) for the NLF ${book.toUpperCase()} book. Generated by tools/deep/bundle.js.\nObject.assign(window.${name} = window.${name} || {}, {\n${body}\n});\n`;
  fs.writeFileSync(path.join(dest, `${book}-${lang}.js`), out);
  sizes[`${book}-${lang}`] = `${Object.keys(all).length} cards, ${(out.length / 1024).toFixed(0)} KB`;
}
console.log(sizes);
